def formatar_real(valor):
    return f'R$ {valor:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')


def aplicar_desconto(preco, percentual):
    desconto = preco * percentual / 100
    return round(preco - desconto, 2)

